from __future__ import annotations

import ipaddress
import json
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import urlparse


class ScopeError(ValueError):
    pass


@dataclass(frozen=True)
class Target:
    target_id: str
    host: str
    ports: tuple[int, ...]


def _safe_ip(value: str) -> ipaddress.IPv4Address:
    try:
        ip = ipaddress.ip_address(value)
    except ValueError as exc:
        raise ScopeError(f"Only literal IP addresses are accepted: {value}") from exc
    if not isinstance(ip, ipaddress.IPv4Address):
        raise ScopeError(f"Only IPv4 targets are accepted: {value}")
    if not (ip.is_loopback or ip.is_private):
        raise ScopeError(f"Target is outside the local/private policy: {value}")
    return ip


def _ports(value: object) -> tuple[int, ...]:
    if value is None:
        return ()
    if not isinstance(value, list):
        raise ScopeError("ports must be a list")
    result=[]
    for port in value:
        if not isinstance(port, int) or not 1 <= port <= 65535:
            raise ScopeError(f"Invalid port: {port!r}")
        result.append(port)
    return tuple(sorted(set(result)))


def validate_url(url: str) -> str:
    parsed=urlparse(url)
    if parsed.scheme not in {"http","https"} or not parsed.hostname:
        raise ScopeError(f"Unsupported or malformed URL: {url}")
    _safe_ip(parsed.hostname)
    if parsed.username or parsed.password:
        raise ScopeError("Credentials are not allowed in scoped URLs")
    return url


def load_scope(path: str | Path):
    data=json.loads(Path(path).read_text(encoding="utf-8"))
    targets_raw=data.get("targets",[])
    urls_raw=data.get("web_urls",[])
    if not isinstance(targets_raw,list):
        raise ScopeError("targets must be a list")
    targets=[]
    seen=set()
    for raw in targets_raw:
        if not isinstance(raw,dict):
            raise ScopeError("Each target must be an object")
        tid=raw.get("id")
        host=raw.get("host")
        if not isinstance(tid,str) or not tid or tid in seen:
            raise ScopeError("Target ids must be unique non-empty strings")
        if not isinstance(host,str):
            raise ScopeError("host must be a string")
        _safe_ip(host)
        targets.append(Target(tid,host,_ports(raw.get("ports"))))
        seen.add(tid)
    urls=[validate_url(v) for v in urls_raw]
    if not targets and not urls:
        raise ScopeError("Scope must contain at least one target or web URL")
    return targets, urls, data

from __future__ import annotations

import hashlib
import json
from pathlib import Path


def sha256_file(path: Path) -> str:
    digest=hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1024*1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def build_index(run_dir: Path):
    records=[]
    for path in sorted(p for p in run_dir.rglob("*") if p.is_file()):
        if path.name == "evidence-index.json":
            continue
        records.append({"path":str(path.relative_to(run_dir)),"bytes":path.stat().st_size,"sha256":sha256_file(path)})
    out=run_dir/"evidence-index.json"
    out.write_text(json.dumps(records,indent=2),encoding="utf-8")
    return out

from __future__ import annotations

import json
from pathlib import Path


def load(path: Path, default):
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else default


def generate_report(run_dir: Path):
    scope=load(run_dir/"scope.json",{})
    services=load(run_dir/"services.json",[])
    findings=load(run_dir/"findings.json",{"findings":[]})
    evidence=load(run_dir/"evidence-index.json",[])
    e=scope.get("engagement",{})
    lines=["# Penetration Testing Assessment Report","",f"- Engagement: {e.get('name','N/A')}",f"- Authorization: {e.get('authorization','N/A')}",f"- Window: {e.get('window','N/A')}","","## Scope","","### Targets"]
    for t in scope.get("targets",[]):
        lines.append(f"- {t.get('id')}: {t.get('host')} ports={t.get('ports',[])}")
    lines += ["","## Methodology","","Scope validation → discovery → enumeration → manual validation → reporting → retesting.","","## Service inventory",""]
    if services:
        lines += ["| Host | Port | Proto | State | Service | Product | Version |","|---|---:|---|---|---|---|---|"]
        for h in services:
            for p in h.get("ports",[]):
                lines.append(f"| {h.get('address')} | {p.get('port')} | {p.get('protocol')} | {p.get('state')} | {p.get('service') or ''} | {p.get('product') or ''} | {p.get('version') or ''} |")
    else:
        lines.append("No parsed Nmap services are present.")
    lines += ["","## Findings",""]
    fs=findings.get("findings",[])
    if not fs:
        lines.append("No tester-authored findings are recorded.")
    for f in fs:
        lines += [f"### {f.get('title','Untitled')}","",f"- Status: {f.get('status','unspecified')}",f"- Severity: {f.get('severity','unspecified')}",f"- Asset: {f.get('asset','unspecified')}",f"- Description: {f.get('description','')}",f"- Impact: {f.get('impact','')}","","#### Reproduction"]
        for step in f.get("reproduction",[]): lines.append(f"1. {step}")
        lines += ["","#### Remediation"]
        for rem in f.get("remediation",[]): lines.append(f"- {rem}")
        lines += ["","#### Evidence"]
        for ev in f.get("evidence",[]): lines.append(f"- `{ev}`")
    lines += ["","## Evidence inventory","","| Artifact | Bytes | SHA-256 |","|---|---:|---|"]
    for item in evidence:
        lines.append(f"| `{item['path']}` | {item['bytes']} | `{item['sha256']}` |")
    lines += ["","## Limitations","","- Results are limited to the authorized local lab scope.","- Scanner alerts are not confirmed vulnerabilities without manual verification.","- Untested systems, routes, ports, and attack paths are not claimed as assessed.",""]
    out=run_dir/"assessment.md"
    out.write_text("\n".join(lines),encoding="utf-8")
    return out

import json
import tempfile
import unittest
from pathlib import Path

from ptw.scope import ScopeError, load_scope, validate_url


class ScopeTests(unittest.TestCase):
    def write_scope(self, data):
        h=tempfile.NamedTemporaryFile('w',delete=False,suffix='.json')
        with h: json.dump(data,h)
        return Path(h.name)

    def test_loopback_and_private_allowed(self):
        p=self.write_scope({'targets':[{'id':'a','host':'127.0.0.1','ports':[80]},{'id':'b','host':'192.168.56.101','ports':[22]}],'web_urls':[]})
        targets,_,_=load_scope(p)
        self.assertEqual(len(targets),2)

    def test_public_rejected(self):
        p=self.write_scope({'targets':[{'id':'a','host':'8.8.8.8','ports':[53]}],'web_urls':[]})
        with self.assertRaises(ScopeError): load_scope(p)

    def test_hostname_rejected(self):
        p=self.write_scope({'targets':[{'id':'a','host':'example.com','ports':[80]}],'web_urls':[]})
        with self.assertRaises(ScopeError): load_scope(p)

    def test_bad_port_rejected(self):
        p=self.write_scope({'targets':[{'id':'a','host':'127.0.0.1','ports':[70000]}],'web_urls':[]})
        with self.assertRaises(ScopeError): load_scope(p)

    def test_url_credentials_rejected(self):
        with self.assertRaises(ScopeError): validate_url('http://user:pass@127.0.0.1:8080/')

    def test_private_url_allowed(self):
        self.assertEqual(validate_url('http://127.0.0.1:8080/'),'http://127.0.0.1:8080/')
